use std::fs

struct Tree {
    key: Vec<int>,
    left: Vec<int>,
    right: Vec<int>,
    root: int,
    found: bool,
}

impl Tree {
    fn add(self, x: int) -> int {
        self.key.push(x)
        self.left.push(-1)
        self.right.push(-1)
        self.key.len() - 1
    }

    fn has(self, x: int) -> bool {
        let mut n = self.root
        while n != -1 {
            let k = self.key[n]
            if x == k { return true }
            if x < k { n = self.left[n] } else { n = self.right[n] }
        }
        false
    }

    fn ins(self, n: int, x: int) -> int {
        if n == -1 { return self.add(x) }
        if x < self.key[n] {
            let c = self.left[n]
            let r = self.ins(c, x)
            self.left[n] = r
        } else {
            let c = self.right[n]
            let r = self.ins(c, x)
            self.right[n] = r
        }
        n
    }

    fn minnode(self, n: int) -> int {
        let mut c = n
        while self.left[c] != -1 { c = self.left[c] }
        c
    }

    fn del(self, n: int, x: int) -> int {
        if n == -1 { return -1 }
        let k = self.key[n]
        if x < k {
            let c = self.left[n]
            let r = self.del(c, x)
            self.left[n] = r
            return n
        }
        if x > k {
            let c = self.right[n]
            let r = self.del(c, x)
            self.right[n] = r
            return n
        }
        self.found = true
        let l = self.left[n]
        let rt = self.right[n]
        if l == -1 { return rt }
        if rt == -1 { return l }
        let s = self.minnode(rt)
        let sk = self.key[s]
        self.key[n] = sk
        let r = self.del(rt, sk)
        self.right[n] = r
        n
    }

    fn walk(self, n: int, out: Vec<int>) {
        if n == -1 { return }
        let l = self.left[n]
        self.walk(l, out)
        out.push(self.key[n])
        let r = self.right[n]
        self.walk(r, out)
    }

    fn hgt(self, n: int) -> int {
        if n == -1 { return 0 }
        let a = self.hgt(self.left[n])
        let b = self.hgt(self.right[n])
        if a > b { a + 1 } else { b + 1 }
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { key: [], left: [], right: [], root: -1, found: false }
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        let mut arg: int = 0
        if parts.len() > 1 { arg = parts[1].parse::<int>().unwrap_or(0) }
        if cmd == "insert" {
            if t.has(arg) {
                println("dup")
            } else {
                let r = t.ins(t.root, arg)
                t.root = r
                println("ok")
            }
        } else if cmd == "contains" {
            if t.has(arg) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            t.found = false
            let r = t.del(t.root, arg)
            t.root = r
            if t.found { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            let mut out: Vec<int> = []
            t.walk(t.root, out)
            if out.len() == 0 {
                println("<empty>")
            } else {
                let strs: Vec<string> = out.map(|v| "${v}").collect()
                println(strs.join(" "))
            }
        } else if cmd == "height" {
            println("${t.hgt(t.root)}")
        } else if cmd == "min" {
            if t.root == -1 { println("empty") } else { println("${t.key[t.minnode(t.root)]}") }
        } else if cmd == "max" {
            if t.root == -1 {
                println("empty")
            } else {
                let mut c = t.root
                while t.right[c] != -1 { c = t.right[c] }
                println("${t.key[c]}")
            }
        }
    }
}

